const AI_IMAGE_MIMES=new Set(['image/jpeg','image/png','image/webp','image/gif']);
async function fileToDataUrl(f){return new Promise((ok,fail)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=fail;r.readAsDataURL(f)})}
async function normalizeImageForAI(file){
  if(AI_IMAGE_MIMES.has((file.type||'').toLowerCase())) return {file,converted:false,originalType:file.type};
  if(!(file.type||'').toLowerCase().startsWith('image/')) throw new Error('الملف المختار ليس صورة.');
  // Chrome/Edge can decode AVIF in the browser even though the OpenAI image input does not accept AVIF.
  // Re-encode unsupported browser-readable formats to JPEG before they ever reach R2/D1.
  let bitmap;
  try{bitmap=await createImageBitmap(file)}catch(e){throw new Error(`صيغة الصورة ${file.type||'غير معروفة'} غير مدعومة للتحليل. احفظها JPG/PNG/WebP ثم أعد رفعها.`)}
  try{
    const maxSide=2400,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
    const w=Math.max(1,Math.round(bitmap.width*scale)),h=Math.max(1,Math.round(bitmap.height*scale));
    const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
    const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(bitmap,0,0,w,h);
    const blob=await new Promise((ok,fail)=>canvas.toBlob(b=>b?ok(b):fail(new Error('تعذر تحويل الصورة إلى JPEG')),'image/jpeg',0.94));
    const base=(file.name||'image').replace(/\.[^.]+$/,'');
    return {file:new File([blob],`${base}-ai.jpg`,{type:'image/jpeg',lastModified:Date.now()}),converted:true,originalType:file.type};
  } finally { if(bitmap&&bitmap.close) bitmap.close(); }
}
async function uploadAsset(){const input=document.querySelector('#file');if(!input.files[0])return toast('اختر صورة','err');const original=input.files[0];try{const n=await normalizeImageForAI(original);if(n.converted)toast(`تم تحويل ${n.originalType||'الصيغة'} تلقائياً إلى JPEG متوافق مع التحليل`);const f=n.file;const dataUrl=await fileToDataUrl(f);await api(`/api/styles/${state.style.style.id}/assets`,{method:'POST',body:JSON.stringify({filename:f.name,originalFilename:original.name,originalMime:n.originalType,dataUrl,role:document.querySelector('#role').value,rightsStatus:'USER_ASSERTED'})});state.style=await api(`/api/styles/${state.style.style.id}`);render();toast('تم رفع الصورة')}catch(x){toast(x.message,'err')}}
async function analyze(){const assetId=document.querySelector('#assetSel').value,provider=document.querySelector('#aiProvider')?.value||'auto';if(!assetId)return toast('ارفع صورة أولاً','err');try{toast(`بدأ التحليل عبر ${provider}...`);const r=await api(`/api/styles/${state.style.style.id}/ai-analyze`,{method:'POST',body:JSON.stringify({assetId,provider})});state.ai=r.result;render();toast(`اكتمل التحليل عبر ${r.provider||provider}`)}catch(x){toast(x.message,'err')}}
async function analyzeMulti(){const sel=document.querySelector('#multiAssetSel'),assetIds=[...sel.selectedOptions].map(x=>x.value),provider=document.querySelector('#aiProvider')?.value||'auto';if(assetIds.length<2)return toast('اختر صورتين على الأقل للتحليل الجماعي','err');try{toast(`بدأ تحليل ${assetIds.length} صور عبر ${provider}...`);const r=await api(`/api/styles/${state.style.style.id}/ai-analyze-multi`,{method:'POST',body:JSON.stringify({assetIds,provider})});state.ai=r.result;render();toast(`اكتمل consensus عبر ${r.provider||provider}; conflicts ${(r.result.conflicts||[]).length}`)}catch(x){toast(x.message,'err')}}
async function applyAI(){if(!state.ai)return;const r=await api(`/api/styles/${state.style.style.id}/apply-ai`,{method:'POST',body:JSON.stringify({result:state.ai})});state.style=await api(`/api/styles/${state.style.style.id}`);render();toast(`AI Draft: DNA ${r.dnaCount||0} / POM ${r.pomCount||0} / Pattern ${r.patternCount||0} / Ops ${r.opCount||0} / Regions ${r.annotationCount||0}`)}
async function renderAudit(){app.innerHTML=shell(`<div class="top"><div><h1>Audit Trail</h1><div class="muted">من عمل ماذا ومتى داخل Workspace.</div></div></div><div class="panel" id="auditBox">جاري التحميل...</div>`);bindShell();try{const d=await api(`/api/audit?orgId=${state.org.id}`);document.querySelector('#auditBox').innerHTML=`<div class="table-wrap"><table><tr><th>الوقت</th><th>Entity</th><th>Action</th><th>Details</th></tr>${d.items.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.entity_type)} ${esc(x.entity_id||'')}</td><td>${esc(x.action)}</td><td><code>${esc(x.detail_json)}</code></td></tr>`).join('')}</table></div>`}catch(x){toast(x.message,'err')}}
async function renderAI(){app.innerHTML=shell(`<div class="top"><div><h1>AI Gateway</h1><div class="muted">المفاتيح تظل على السيرفر. Auto Router يدعم Claude + OpenAI مع fallback.</div></div></div><div class="panel" id="aiBox">جاري التحميل...</div>`);bindShell();try{const d=await api('/api/ai/providers');state.providers=d.providers||[];document.querySelector('#aiBox').innerHTML=`<div class="grid">${d.providers.map(p=>`<div class="card provider-card"><h3>${esc(p.id)}</h3><p>Model: ${esc(p.model||'—')}</p><p class="tag">${p.configured?'Configured':'Not configured'}</p><p class="muted">${esc(p.note||'')}${p.enabled?' · مفعّل':''}</p></div>`).join('')}</div><div class="notice" style="margin-top:14px"><b>Claude runtime:</b> ضع ANTHROPIC_API_KEY وANTHROPIC_MODEL على Cloudflare/Codespaces. اشتراك Claude/GitHub Connector مفيد للتطوير وClaude Code، لكنه ليس بديلاً تلقائياً عن مفتاح Anthropic API داخل Worker.</div><div class="notice ok" style="margin-top:10px"><b>Auto Router:</b> المتغير AI_PROVIDER_ORDER=anthropic,openai يجعل Claude أولاً، وإذا فشل بسبب quota/provider error ينتقل إلى OpenAI تلقائياً.</div>`}catch(x){toast(x.message,'err')}}
